using WarehouseBarcode;
using Microsoft.Extensions.FileProviders;
var builder = WebApplication.CreateBuilder(args); builder.Services.AddSingleton<DataStoreService>(); builder.Services.AddSingleton<CaptchaService>(); builder.Services.AddSingleton<PasswordService>(); var app = builder.Build();
app.MapGet("/api/dashboard", (DataStoreService store) => { var d = store.Data; return new { products = d.Products.Count(x => x.Active), warehouses = d.Warehouses.Count(x => x.Active), partners = d.Partners.Count(x => x.Active), lowStock = d.Stock.Count(s => d.Products.Any(p => p.Id == s.ProductId && p.Active && s.Quantity <= p.SafetyStock)), recent = d.Transactions.OrderByDescending(x => x.OccurredAt).Take(10).Select(x => new { x.DocumentNo, x.Type, x.Quantity, product = d.Products.FirstOrDefault(p => p.Id == x.ProductId)?.Name, warehouse = d.Warehouses.FirstOrDefault(w => w.Id == x.WarehouseId)?.Name, x.OccurredAt }) }; });
app.MapGet("/api/dashboard/alerts", (DataStoreService store) => { var d = store.Data; return d.Stock.Where(s => d.Products.Any(p => p.Id == s.ProductId && s.Quantity <= p.SafetyStock)).Select(s => { var p = d.Products.First(x => x.Id == s.ProductId); return new { product = p.Name, warehouse = d.Warehouses.FirstOrDefault(w => w.Id == s.WarehouseId)?.Name, quantity = s.Quantity, safetyStock = p.SafetyStock }; }); });
app.MapGet("/api/dashboard/warehouse-distribution", (DataStoreService store) => { var d = store.Data; var rows = d.Warehouses.Where(x => x.Active).Select(w => new { warehouse = w.Name, quantity = d.Stock.Where(s => s.WarehouseId == w.Id).Sum(s => s.Quantity) }).ToList(); var max = rows.Select(x => x.quantity).DefaultIfEmpty(1).Max(); return rows.Select(x => new { x.warehouse, x.quantity, percent = max == 0 ? 0 : x.quantity / max * 100 }); });
app.MapGet("/api/dashboard/daily-trend", (DataStoreService store) => { var d = store.Data; return Enumerable.Range(0, 7).Select(i => { var date = DateTime.UtcNow.Date.AddDays(-6 + i); var rows = d.Transactions.Where(x => x.OccurredAt.ToLocalTime().Date == date); return new { date = date.ToString("yyyy-MM-dd"), inbound = rows.Where(x => x.Type.Contains("入库")).Sum(x => x.Quantity), outbound = rows.Where(x => x.Type.Contains("出库")).Sum(x => x.Quantity) }; }); });
app.MapGet("/api/products", (DataStoreService store) => store.Data.Products.Where(x => x.Active).OrderBy(x => x.Sku)); app.MapGet("/api/warehouses", (DataStoreService store) => store.Data.Warehouses.Where(x => x.Active));
app.MapGet("/api/stock", (DataStoreService store) => { var d = store.Data; return d.Stock.OrderBy(x => d.Products.FirstOrDefault(p => p.Id == x.ProductId)?.Sku).Select(x => { var p = d.Products.FirstOrDefault(p => p.Id == x.ProductId); var w = d.Warehouses.FirstOrDefault(w => w.Id == x.WarehouseId); var l = x.LocationId is null ? null : d.Locations.FirstOrDefault(y => y.Id == x.LocationId); return new { x.Id, sku = p?.Sku ?? "", barcode = p?.Barcode ?? "", product = p?.Name ?? "", warehouse = w?.Name ?? "", location = l?.Code, batchNo = x.BatchNo, x.ProducedAt, x.ExpiryDate, x.Status, x.Quantity, unit = p?.Unit ?? "", safetyStock = p?.SafetyStock ?? 0 }; }); });
app.MapGet("/api/locations", (int? warehouseId, DataStoreService store) => store.Data.Locations.Where(x => warehouseId is null || x.WarehouseId == warehouseId && x.Status == "启用"));
app.MapPost("/api/locations", (LocationRequest r, DataStoreService store) => { if (!store.Data.Warehouses.Any(x => x.Id == r.WarehouseId && x.Active) || string.IsNullOrWhiteSpace(r.Code)) return Results.BadRequest("仓库和库位编码必填"); if (store.Data.Locations.Any(x => x.Code == r.Code)) return Results.Conflict("库位编码已存在"); var item = new WarehouseLocation { Id = store.Data.NextId(), WarehouseId = r.WarehouseId, Zone = r.Zone, Shelf = r.Shelf, Level = r.Level, Code = r.Code, Capacity = Math.Max(0, r.Capacity) }; store.Mutate(d => d.Locations.Add(item)); return Results.Ok(item); });
app.MapGet("/api/documents", (string? type, string? status, DataStoreService store) => store.Data.Documents.Where(x => (string.IsNullOrWhiteSpace(type) || x.DocumentType == type) && (string.IsNullOrWhiteSpace(status) || x.Status == status)).OrderByDescending(x => x.DocumentDate).Select(x => new { x.Id, x.DocumentNo, x.DocumentType, x.DocumentDate, x.WarehouseId, x.PartnerId, x.Status, x.Remark, lines = x.Lines }));
app.MapGet("/api/documents/{id:long}", (long id, DataStoreService store) => store.Data.Documents.SingleOrDefault(x => x.Id == id) is { } d ? Results.Ok(d) : Results.NotFound());
app.MapGet("/print/document/{id:long}", (long id, DataStoreService store) => { var d = store.Data.Documents.SingleOrDefault(x => x.Id == id); if (d is null) return Results.NotFound(); var rows = string.Join("", d.Lines.Select(x => $"<tr><td>{x.ProductId}</td><td>{x.BatchNo}</td><td>{x.LocationId}</td><td>{x.Quantity}</td></tr>")); return Results.Content($"<!doctype html><meta charset='utf-8'><title>{d.DocumentNo}</title><style>body{{font-family:system-ui;max-width:900px;margin:30px auto}}table{{width:100%;border-collapse:collapse}}td,th{{border:1px solid #999;padding:8px}}@media print{{button{{display:none}}}}</style><h1>{d.DocumentType}</h1><p>单号：{d.DocumentNo}　状态：{d.Status}</p><table><thead><tr><th>商品</th><th>批次</th><th>库位</th><th>数量</th></tr></thead><tbody>{rows}</tbody></table><button onclick='print()'>打印 / 保存 PDF</button>", "text/html; charset=utf-8"); });
app.MapPost("/api/documents", (DocumentRequest r, HttpContext http, DataStoreService store) =>
{
    var validTypes = new[] { "入库单", "出库单", "销售退货单" }; if (!validTypes.Contains(r.DocumentType) || r.WarehouseId <= 0 || r.Lines is null || r.Lines.Count == 0) return Results.BadRequest("单据类型、仓库和明细必填");
    var d = store.Data; if (!d.Warehouses.Any(x => x.Id == r.WarehouseId && x.Active)) return Results.NotFound("仓库不存在"); if (r.PartnerId is not null && !d.Partners.Any(x => x.Id == r.PartnerId && x.Active)) return Results.NotFound("往来单位不存在");
    foreach (var l in r.Lines) { if (l.Quantity <= 0 || !d.Products.Any(x => x.Id == l.ProductId && x.Active)) return Results.BadRequest("商品或数量无效"); }
    var id = d.Documents.Count == 0 ? 1 : d.Documents.Max(x => x.Id) + 1; var prefix = r.DocumentType == "入库单" ? "IN" : r.DocumentType == "出库单" ? "OUT" : "RT"; var no = $"{prefix}-{DateTime.Now:yyyyMMddHHmmss}-{id:0000}"; var user = http.Request.Cookies["warehouse_session"];
    var doc = new BusinessDocument { Id = id, DocumentNo = no, DocumentType = r.DocumentType, WarehouseId = r.WarehouseId, PartnerId = r.PartnerId, Remark = r.Remark, CreatedBy = user, Lines = r.Lines.Select((l, i) => new BusinessDocumentLine { Id = i + 1, DocumentId = id, ProductId = l.ProductId, Quantity = l.Quantity, LocationId = l.LocationId, Barcode = l.Barcode ?? d.Products.First(x => x.Id == l.ProductId).Barcode, BatchNo = l.BatchNo, ProducedAt = l.ProducedAt, ExpiryDate = l.ExpiryDate, QualityStatus = l.QualityStatus, Remark = l.Remark }).ToList() }; store.Mutate(x => x.Documents.Add(doc)); return Results.Ok(doc);
});
app.MapPost("/api/documents/{id:long}/submit", (long id, DataStoreService store) => { var doc = store.Data.Documents.SingleOrDefault(x => x.Id == id); if (doc is null) return Results.NotFound(); if (doc.Status != "草稿") return Results.BadRequest("只有草稿可以提交"); store.Mutate(_ => doc.Status = "已提交"); return Results.Ok(doc); });
app.MapPost("/api/documents/{id:long}/approve", (long id, HttpContext http, DataStoreService store) =>
{
    var doc = store.Data.Documents.SingleOrDefault(x => x.Id == id); if (doc is null) return Results.NotFound(); if (doc.Status != "已提交") return Results.BadRequest("只有已提交单据可以审核"); var d = store.Data;
    if (doc.DocumentType == "出库单") { foreach (var l in doc.Lines) { var available = d.Stock.Where(x => x.ProductId == l.ProductId && x.WarehouseId == doc.WarehouseId && x.Status == "正常" && (x.ExpiryDate == null || x.ExpiryDate > DateTime.UtcNow)).Sum(x => x.Quantity); if (available < l.Quantity) return Results.BadRequest($"商品 {l.ProductId} 可用库存不足"); } }
    store.Mutate(data => { foreach (var l in doc.Lines) { var type = doc.DocumentType == "入库单" ? "入库" : doc.DocumentType == "出库单" ? "出库" : "退货入库"; var delta = doc.DocumentType == "出库单" ? -l.Quantity : l.Quantity; if (doc.DocumentType == "出库单") { var p = data.Products.First(x => x.Id == l.ProductId); var q = data.Stock.Where(x => x.ProductId == l.ProductId && x.WarehouseId == doc.WarehouseId && x.Status == "正常" && (x.ExpiryDate == null || x.ExpiryDate > DateTime.UtcNow)).OrderBy(x => p.IssueStrategy == "FEFO" ? (x.ExpiryDate ?? DateTime.MaxValue) : x.ReceivedAt).ToList(); var remaining = l.Quantity; foreach (var b in q) { var used = Math.Min(remaining, b.Quantity); b.Quantity -= used; remaining -= used; data.Transactions.Add(new StockTransaction { Id = data.Transactions.Count + 1, DocumentNo = $"{doc.DocumentNo}-{l.Id}", SourceDocumentNo = doc.DocumentNo, Type = type, ProductId = l.ProductId, WarehouseId = doc.WarehouseId, Quantity = used, Remark = $"批次:{b.BatchNo}" }); if (remaining <= 0) break; } } else { var b = data.Stock.FirstOrDefault(x => x.ProductId == l.ProductId && x.WarehouseId == doc.WarehouseId && x.LocationId == l.LocationId && x.BatchNo == (l.BatchNo ?? "LEGACY-IMPORT") && x.Status == (l.QualityStatus == "报废" ? "报废" : l.QualityStatus == "待检" ? "待检" : "正常")); if (b is null) data.Stock.Add(new StockBalance { Id = data.NextId(), ProductId = l.ProductId, WarehouseId = doc.WarehouseId, LocationId = l.LocationId, BatchNo = l.BatchNo ?? "LEGACY-IMPORT", ProducedAt = l.ProducedAt, ExpiryDate = l.ExpiryDate, Status = l.QualityStatus == "报废" ? "报废" : l.QualityStatus == "待检" ? "待检" : "正常", ReceivedAt = DateTime.UtcNow, Quantity = l.Quantity }); else b.Quantity += l.Quantity; data.Transactions.Add(new StockTransaction { Id = data.Transactions.Count + 1, DocumentNo = $"{doc.DocumentNo}-{l.Id}", SourceDocumentNo = doc.DocumentNo, Type = type, ProductId = l.ProductId, WarehouseId = doc.WarehouseId, Quantity = l.Quantity, Remark = $"批次:{l.BatchNo}" }); } } doc.Status = "已完成"; doc.Auditor = http.Request.Cookies["warehouse_session"]; doc.AuditedAt = DateTime.UtcNow; doc.CompletedAt = DateTime.UtcNow; }); return Results.Ok(doc);
});
app.MapPost("/api/documents/{id:long}/cancel", (long id, DataStoreService store) => { var doc = store.Data.Documents.SingleOrDefault(x => x.Id == id); if (doc is null) return Results.NotFound(); if (doc.Status == "已完成") return Results.BadRequest("已完成单据不能直接取消，请使用反向单据"); if (doc.Status == "已取消") return Results.BadRequest("单据已取消"); store.Mutate(_ => doc.Status = "已取消"); return Results.Ok(doc); });
app.MapPost("/api/documents/{id:long}/reverse", (long id, ReverseDocumentRequest r, HttpContext http, DataStoreService store) => { var source = store.Data.Documents.SingleOrDefault(x => x.Id == id); if (source is null) return Results.NotFound(); if (source.Status != "已完成") return Results.BadRequest("只有已完成单据可以冲销"); if (store.Data.Documents.Any(x => x.Remark != null && x.Remark.Contains($"冲销:{source.DocumentNo}"))) return Results.Conflict("该单据已经冲销"); var type = source.DocumentType == "出库单" ? "入库单" : source.DocumentType == "入库单" ? "出库单" : "销售退货单"; var rid = store.Data.Documents.Count == 0 ? 1 : store.Data.Documents.Max(x => x.Id) + 1; var reverse = new BusinessDocument { Id = rid, DocumentNo = $"REV-{DateTime.Now:yyyyMMddHHmmss}-{rid:0000}", DocumentType = type, WarehouseId = source.WarehouseId, PartnerId = source.PartnerId, Remark = $"冲销:{source.DocumentNo} {r.Remark}", CreatedBy = http.Request.Cookies["warehouse_session"], Lines = source.Lines.Select((l, i) => new BusinessDocumentLine { Id = i + 1, DocumentId = rid, ProductId = l.ProductId, Quantity = l.Quantity, LocationId = l.LocationId, BatchNo = l.BatchNo, ProducedAt = l.ProducedAt, ExpiryDate = l.ExpiryDate, QualityStatus = l.QualityStatus, Barcode = l.Barcode }).ToList() }; store.Mutate(d => d.Documents.Add(reverse)); return Results.Ok(reverse); });
app.MapPost("/api/transactions", (TransactionRequest request, DataStoreService store) => { var d = store.Data; if (request.Quantity <= 0 || !new[] { "入库", "出库", "退货入库" }.Contains(request.Type)) return Results.BadRequest("业务类型或数量无效"); var product = d.Products.SingleOrDefault(x => x.Id == request.ProductId && x.Active); var warehouse = d.Warehouses.SingleOrDefault(x => x.Id == request.WarehouseId && x.Active); if (product is null || warehouse is null) return Results.NotFound("商品或仓库不存在"); var balance = d.Stock.SingleOrDefault(x => x.ProductId == product.Id && x.WarehouseId == warehouse.Id); var quantity = balance?.Quantity ?? 0; var delta = request.Type == "出库" ? -request.Quantity : request.Quantity; if (quantity + delta < 0) return Results.BadRequest("库存不足"); store.Mutate(data => { var current = data.Stock.SingleOrDefault(x => x.ProductId == product.Id && x.WarehouseId == warehouse.Id); if (current is null) data.Stock.Add(new StockBalance { Id = data.NextId(), ProductId = product.Id, WarehouseId = warehouse.Id, Quantity = delta }); else current.Quantity += delta; data.Transactions.Add(new StockTransaction { Id = data.Transactions.Count + 1, DocumentNo = $"{(request.Type == "出库" ? "OUT" : "IN")}-{DateTime.Now:yyyyMMddHHmmssfff}", Type = request.Type, ProductId = product.Id, WarehouseId = warehouse.Id, Quantity = request.Quantity, Remark = request.Remark }); }); return Results.Ok(new { quantity = quantity + delta }); });
app.MapGet("/api/transactions", (DataStoreService store) => { var d = store.Data; return d.Transactions.OrderByDescending(x => x.OccurredAt).Select(x => new { x.Id, x.DocumentNo, x.OccurredAt, x.Type, x.Quantity, x.Remark, product = d.Products.FirstOrDefault(p => p.Id == x.ProductId)?.Name, warehouse = d.Warehouses.FirstOrDefault(w => w.Id == x.WarehouseId)?.Name }); });
app.MapPost("/api/products", (ProductRequest r, DataStoreService store) => { if (string.IsNullOrWhiteSpace(r.Sku) || string.IsNullOrWhiteSpace(r.Barcode) || string.IsNullOrWhiteSpace(r.Name)) return Results.BadRequest("SKU、条码和名称必填"); if (store.Data.Products.Any(x => x.Sku == r.Sku || x.Barcode == r.Barcode)) return Results.Conflict("SKU或条码已存在"); var item = new Product { Id = store.Data.NextId(), Sku = r.Sku.Trim(), Barcode = r.Barcode.Trim(), Name = r.Name.Trim(), Unit = string.IsNullOrWhiteSpace(r.Unit) ? "件" : r.Unit.Trim(), SafetyStock = Math.Max(0, r.SafetyStock) }; store.Mutate(d => d.Products.Add(item)); return Results.Ok(item); });
app.MapPost("/api/warehouses", (WarehouseRequest r, DataStoreService store) => { if (string.IsNullOrWhiteSpace(r.Code) || string.IsNullOrWhiteSpace(r.Name)) return Results.BadRequest("仓库编码和名称必填"); if (store.Data.Warehouses.Any(x => x.Code == r.Code)) return Results.Conflict("仓库编码已存在"); var item = new Warehouse { Id = store.Data.NextId(), Code = r.Code.Trim(), Name = r.Name.Trim(), Address = r.Address?.Trim() }; store.Mutate(d => d.Warehouses.Add(item)); return Results.Ok(item); });
app.MapPost("/api/partners", (PartnerRequest r, DataStoreService store) => { if (string.IsNullOrWhiteSpace(r.Code) || string.IsNullOrWhiteSpace(r.Name)) return Results.BadRequest("单位编码和名称必填"); if (store.Data.Partners.Any(x => x.Code == r.Code)) return Results.Conflict("往来单位编码已存在"); var item = new BusinessPartner { Id = store.Data.NextId(), Code = r.Code.Trim(), Name = r.Name.Trim(), Type = string.IsNullOrWhiteSpace(r.Type) ? "客户/供应商" : r.Type.Trim() }; store.Mutate(d => d.Partners.Add(item)); return Results.Ok(item); });
app.MapDelete("/api/products/{id:int}", (int id, DataStoreService store) => { var item = store.Data.Products.SingleOrDefault(x => x.Id == id); if (item is null) return Results.NotFound(); if (store.Data.Stock.Any(x => x.ProductId == id && x.Quantity != 0)) return Results.BadRequest("仍有库存的商品不能停用"); store.Mutate(_ => item.Active = false); return Results.NoContent(); });
app.MapDelete("/api/warehouses/{id:int}", (int id, DataStoreService store) => { var item = store.Data.Warehouses.SingleOrDefault(x => x.Id == id); if (item is null) return Results.NotFound(); if (store.Data.Stock.Any(x => x.WarehouseId == id && x.Quantity != 0)) return Results.BadRequest("仍有库存的仓库不能停用"); store.Mutate(_ => item.Active = false); return Results.NoContent(); });
app.MapPost("/api/stocktakes", (StocktakeRequest r, DataStoreService store) => { var d = store.Data; if (r.Actual < 0) return Results.BadRequest("实盘数量不能为负数"); if (!d.Products.Any(x => x.Id == r.ProductId && x.Active) || !d.Warehouses.Any(x => x.Id == r.WarehouseId && x.Active)) return Results.NotFound("商品或仓库不存在"); var balance = d.Stock.SingleOrDefault(x => x.ProductId == r.ProductId && x.WarehouseId == r.WarehouseId); var before = balance?.Quantity ?? 0; var diff = r.Actual - before; store.Mutate(data => { var current = data.Stock.SingleOrDefault(x => x.ProductId == r.ProductId && x.WarehouseId == r.WarehouseId); if (current is null) data.Stock.Add(new StockBalance { Id = data.NextId(), ProductId = r.ProductId, WarehouseId = r.WarehouseId, Quantity = r.Actual }); else current.Quantity = r.Actual; data.Stocktakes.Add(new Stocktake { Id = data.Stocktakes.Count + 1, ProductId = r.ProductId, WarehouseId = r.WarehouseId, Before = before, After = r.Actual, Difference = diff, Remark = r.Remark }); data.Transactions.Add(new StockTransaction { Id = data.Transactions.Count + 1, DocumentNo = $"ST-{DateTime.Now:yyyyMMddHHmmssfff}", Type = "盘点调整", ProductId = r.ProductId, WarehouseId = r.WarehouseId, Quantity = Math.Abs(diff), Remark = $"{r.Remark} 前{before} 后{r.Actual}" }); }); return Results.Ok(new { before, after = r.Actual, difference = diff }); });
app.MapGet("/api/stocktake-documents", (DataStoreService store) => store.Data.StocktakeDocuments.OrderByDescending(x => x.DocumentDate));
app.MapPost("/api/stocktake-documents", (StocktakeDocumentRequest r, HttpContext http, DataStoreService store) => { if (r.Lines is null || r.Lines.Count == 0) return Results.BadRequest("盘点明细不能为空"); var d = store.Data; if (!d.Warehouses.Any(x => x.Id == r.WarehouseId && x.Active)) return Results.NotFound("仓库不存在"); var id = d.StocktakeDocuments.Count == 0 ? 1 : d.StocktakeDocuments.Max(x => x.Id) + 1; var lines = r.Lines.Select((l, i) => { var q = d.Stock.Where(s => s.ProductId == l.ProductId && s.WarehouseId == r.WarehouseId && s.LocationId == l.LocationId && (string.IsNullOrWhiteSpace(l.BatchNo) || s.BatchNo == l.BatchNo)).Sum(s => s.Quantity); return new StocktakeLine { Id = i + 1, ProductId = l.ProductId, LocationId = l.LocationId, BatchNo = l.BatchNo, BookQuantity = q, ActualQuantity = l.ActualQuantity }; }).ToList(); var doc = new StocktakeDocument { Id = id, DocumentNo = $"ST-{DateTime.Now:yyyyMMddHHmmss}-{id:0000}", WarehouseId = r.WarehouseId, Remark = r.Remark, CreatedBy = http.Request.Cookies["warehouse_session"], Lines = lines }; store.Mutate(x => x.StocktakeDocuments.Add(doc)); return Results.Ok(doc); });
app.MapPost("/api/stocktake-documents/{id:long}/submit", (long id, DataStoreService store) => { var x = store.Data.StocktakeDocuments.SingleOrDefault(y => y.Id == id); if (x is null) return Results.NotFound(); if (x.Status != "草稿") return Results.BadRequest("只有草稿可以提交"); store.Mutate(_ => x.Status = "已提交"); return Results.Ok(x); });
app.MapPost("/api/stocktake-documents/{id:long}/approve", (long id, HttpContext http, DataStoreService store) => { var x = store.Data.StocktakeDocuments.SingleOrDefault(y => y.Id == id); if (x is null) return Results.NotFound(); if (x.Status != "已提交") return Results.BadRequest("只有已提交盘点单可以审核"); store.Mutate(data => { foreach (var l in x.Lines) { var b = data.Stock.FirstOrDefault(s => s.ProductId == l.ProductId && s.WarehouseId == x.WarehouseId && s.LocationId == l.LocationId && s.BatchNo == (l.BatchNo ?? "LEGACY-IMPORT")); var diff = l.ActualQuantity - l.BookQuantity; if (b is null && l.ActualQuantity > 0) data.Stock.Add(new StockBalance { Id = data.NextId(), ProductId = l.ProductId, WarehouseId = x.WarehouseId, LocationId = l.LocationId, BatchNo = l.BatchNo ?? "LEGACY-IMPORT", Quantity = l.ActualQuantity }); else if (b is not null) b.Quantity = l.ActualQuantity; data.Transactions.Add(new StockTransaction { Id = data.Transactions.Count + 1, DocumentNo = x.DocumentNo, SourceDocumentNo = x.DocumentNo, Type = "盘点调整", ProductId = l.ProductId, WarehouseId = x.WarehouseId, Quantity = Math.Abs(diff), Remark = $"账面:{l.BookQuantity} 实盘:{l.ActualQuantity}" }); } x.Status = "已完成"; x.Auditor = http.Request.Cookies["warehouse_session"]; }); return Results.Ok(x); });
app.MapGet("/api/stocktake-documents/{id:long}/export", (long id, DataStoreService store) => { var x = store.Data.StocktakeDocuments.SingleOrDefault(y => y.Id == id); if (x is null) return Results.NotFound(); var rows = new[] { "商品ID,批次,账面数量,实盘数量,差异" }.Concat(x.Lines.Select(l => $"{l.ProductId},{l.BatchNo},{l.BookQuantity},{l.ActualQuantity},{l.Difference}")); return Results.Text(string.Join("\n", rows), "text/csv; charset=utf-8"); });
app.MapPost("/api/transfers", (TransferRequest r, DataStoreService store) => { var d = store.Data; if (r.Quantity <= 0 || r.FromWarehouseId == r.ToWarehouseId) return Results.BadRequest("调拨数量或仓库无效"); if (!d.Products.Any(x => x.Id == r.ProductId && x.Active) || !d.Warehouses.Any(x => x.Id == r.FromWarehouseId && x.Active) || !d.Warehouses.Any(x => x.Id == r.ToWarehouseId && x.Active)) return Results.NotFound("商品或仓库不存在"); var from = d.Stock.SingleOrDefault(x => x.ProductId == r.ProductId && x.WarehouseId == r.FromWarehouseId); if ((from?.Quantity ?? 0) < r.Quantity) return Results.BadRequest("来源仓库存不足"); store.Mutate(data => { var source = data.Stock.Single(x => x.ProductId == r.ProductId && x.WarehouseId == r.FromWarehouseId); source.Quantity -= r.Quantity; var target = data.Stock.SingleOrDefault(x => x.ProductId == r.ProductId && x.WarehouseId == r.ToWarehouseId); if (target is null) data.Stock.Add(new StockBalance { Id = data.NextId(), ProductId = r.ProductId, WarehouseId = r.ToWarehouseId, Quantity = r.Quantity }); else target.Quantity += r.Quantity; var no = $"TR-{DateTime.Now:yyyyMMddHHmmssfff}"; data.Transactions.Add(new StockTransaction { Id = data.Transactions.Count + 1, DocumentNo = no, Type = "调拨出库", ProductId = r.ProductId, WarehouseId = r.FromWarehouseId, Quantity = r.Quantity, Remark = r.Remark }); data.Transactions.Add(new StockTransaction { Id = data.Transactions.Count + 1, DocumentNo = no, Type = "调拨入库", ProductId = r.ProductId, WarehouseId = r.ToWarehouseId, Quantity = r.Quantity, Remark = r.Remark }); }); return Results.Ok(); });
app.MapGet("/api/transfer-documents", (DataStoreService store) => store.Data.TransferDocuments.OrderByDescending(x => x.DocumentDate));
app.MapPost("/api/transfer-documents", (TransferDocumentRequest r, HttpContext http, DataStoreService store) => { if (r.FromWarehouseId == r.ToWarehouseId || r.Lines is null || r.Lines.Count == 0) return Results.BadRequest("来源、目标仓库和明细必填"); var d = store.Data; if (!d.Warehouses.Any(x => x.Id == r.FromWarehouseId && x.Active) || !d.Warehouses.Any(x => x.Id == r.ToWarehouseId && x.Active)) return Results.NotFound("仓库不存在"); var id = d.TransferDocuments.Count == 0 ? 1 : d.TransferDocuments.Max(x => x.Id) + 1; var doc = new TransferDocument { Id = id, DocumentNo = $"TR-{DateTime.Now:yyyyMMddHHmmss}-{id:0000}", FromWarehouseId = r.FromWarehouseId, ToWarehouseId = r.ToWarehouseId, Remark = r.Remark, CreatedBy = http.Request.Cookies["warehouse_session"], Lines = r.Lines.Select((x, i) => new TransferLine { Id = i + 1, ProductId = x.ProductId, Quantity = x.Quantity, SourceLocationId = x.LocationId, TargetLocationId = x.LocationId, BatchNo = x.BatchNo }).ToList() }; store.Mutate(x => x.TransferDocuments.Add(doc)); return Results.Ok(doc); });
app.MapPost("/api/transfer-documents/{id:long}/submit", (long id, DataStoreService store) => { var x = store.Data.TransferDocuments.SingleOrDefault(y => y.Id == id); if (x is null) return Results.NotFound(); if (x.Status != "草稿") return Results.BadRequest("只有草稿可以提交"); store.Mutate(_ => x.Status = "已提交"); return Results.Ok(x); });
app.MapPost("/api/transfer-documents/{id:long}/approve", (long id, HttpContext http, DataStoreService store) => { var x = store.Data.TransferDocuments.SingleOrDefault(y => y.Id == id); if (x is null) return Results.NotFound(); if (x.Status != "已提交") return Results.BadRequest("只有已提交调拨单可以审核"); var d = store.Data; foreach (var l in x.Lines) { var b = d.Stock.Where(s => s.ProductId == l.ProductId && s.WarehouseId == x.FromWarehouseId && s.Status == "正常" && (string.IsNullOrWhiteSpace(l.BatchNo) || s.BatchNo == l.BatchNo)).Sum(s => s.Quantity); if (b < l.Quantity) return Results.BadRequest("来源仓库存不足"); } store.Mutate(data => { foreach (var l in x.Lines) { var source = data.Stock.Where(s => s.ProductId == l.ProductId && s.WarehouseId == x.FromWarehouseId && s.Status == "正常" && (string.IsNullOrWhiteSpace(l.BatchNo) || s.BatchNo == l.BatchNo)).OrderBy(s => s.ReceivedAt).First(); source.Quantity -= l.Quantity; var target = data.Stock.FirstOrDefault(s => s.ProductId == l.ProductId && s.WarehouseId == x.ToWarehouseId && s.BatchNo == source.BatchNo && s.LocationId == l.TargetLocationId && s.Status == "正常"); if (target is null) data.Stock.Add(new StockBalance { Id = data.NextId(), ProductId = l.ProductId, WarehouseId = x.ToWarehouseId, LocationId = l.TargetLocationId, BatchNo = source.BatchNo, ProducedAt = source.ProducedAt, ExpiryDate = source.ExpiryDate, ReceivedAt = DateTime.UtcNow, Quantity = l.Quantity }); else target.Quantity += l.Quantity; data.Transactions.Add(new StockTransaction { Id = data.Transactions.Count + 1, DocumentNo = x.DocumentNo, SourceDocumentNo = x.DocumentNo, Type = "调拨出库", ProductId = l.ProductId, WarehouseId = x.FromWarehouseId, Quantity = l.Quantity }); data.Transactions.Add(new StockTransaction { Id = data.Transactions.Count + 1, DocumentNo = x.DocumentNo, SourceDocumentNo = x.DocumentNo, Type = "调拨入库", ProductId = l.ProductId, WarehouseId = x.ToWarehouseId, Quantity = l.Quantity }); } x.Status = "已完成"; x.Auditor = http.Request.Cookies["warehouse_session"]; x.CompletedAt = DateTime.UtcNow; }); return Results.Ok(x); });
app.MapPost("/api/login", (LoginRequest r, DataStoreService store) => { var user = store.Data.Users.SingleOrDefault(x => x.Active && x.Username == r.Username && x.Password == r.Password); return user is null ? Results.Unauthorized() : Results.Ok(new { user.Username, user.Role }); });
app.MapGet("/api/auth/captcha", (CaptchaService captcha, HttpContext http) => { http.Response.Headers.CacheControl = "no-store, no-cache, must-revalidate"; http.Response.Headers.Pragma = "no-cache"; return Results.Ok(captcha.Create()); });
app.MapGet("/api/auth/status", (HttpContext http, DataStoreService store) => { var username = http.Request.Cookies["warehouse_session"]; var user = store.Data.Users.SingleOrDefault(x => x.Active && x.Username == username); return user is null ? Results.Ok(new { authenticated = false }) : Results.Ok(new { authenticated = true, user.Username, user.Role }); });
app.MapPost("/api/auth/login", (AuthLoginRequest r, HttpContext http, DataStoreService store, CaptchaService captcha, PasswordService passwords, ILogger<Program> log) => { log.LogInformation("登录请求 username={Username}, captchaIdProvided={HasCaptchaId}, captchaCodeProvided={HasCaptchaCode}", r.Username, !string.IsNullOrWhiteSpace(r.CaptchaId), !string.IsNullOrWhiteSpace(r.CaptchaCode)); if (!captcha.Verify(r.CaptchaId, r.CaptchaCode)) { log.LogWarning("登录失败 username={Username}, reason=captcha", r.Username); return Results.BadRequest("验证码错误或已过期，请刷新验证码后重试"); } var user = store.Data.Users.SingleOrDefault(x => x.Active && x.Username == r.Username); if (user is null) { log.LogWarning("登录失败 username={Username}, reason=user-not-found-or-inactive", r.Username); return Results.BadRequest("用户名不存在或账号已停用"); } var passwordOk = passwords.Verify(r.Password, user.Password); log.LogInformation("密码校验 username={Username}, matched={Matched}", r.Username, passwordOk); if (!passwordOk) { log.LogWarning("登录失败 username={Username}, reason=password", r.Username); return Results.BadRequest("密码错误"); } store.Mutate(d => { var item = d.Users.Single(x => x.Username == user.Username); item.LastLoginAt = DateTime.UtcNow; }); http.Response.Cookies.Append("warehouse_session", user.Username, new CookieOptions { HttpOnly = true, SameSite = SameSiteMode.Lax, Secure = false, MaxAge = TimeSpan.FromHours(8) }); log.LogInformation("登录成功 username={Username}", user.Username); return Results.Ok(new { user.Username, user.Role, message = "登录成功" }); });
app.MapPost("/api/auth/logout", (HttpContext http) => { http.Response.Cookies.Delete("warehouse_session"); return Results.Ok(); });
app.MapGet("/api/account/profile", (HttpContext http, DataStoreService store) => { var username = http.Request.Cookies["warehouse_session"]; var user = store.Data.Users.SingleOrDefault(x => x.Active && x.Username == username); return user is null ? Results.Unauthorized() : Results.Ok(new { user.Username, user.DisplayName, user.Role, user.Phone, user.LastLoginAt }); });
app.MapPost("/api/system/backup", (HttpContext http, DataStoreService store) => { var file = Path.Combine(Path.GetTempPath(), $"warehouse-backup-{DateTime.UtcNow:yyyyMMddHHmmss}.json"); store.Backup(file); return Results.Ok(new { file }); });
app.MapGet("/documents", () => Results.File(Path.Combine(app.Environment.WebRootPath!, "documents.html"), "text/html; charset=utf-8"));
app.Use(async (http, next) => { if (http.Request.Path.StartsWithSegments("/api") && !http.Request.Path.StartsWithSegments("/api/auth")) { var username = http.Request.Cookies["warehouse_session"]; var valid = app.Services.GetRequiredService<DataStoreService>().Data.Users.Any(x => x.Active && x.Username == username); if (!valid) { http.Response.StatusCode = StatusCodes.Status401Unauthorized; await http.Response.WriteAsJsonAsync(new { message = "请先登录" }); return; } } await next(); });
var reactRoot = Path.GetFullPath(Path.Combine(app.Environment.ContentRootPath, "..", "frontend", "dist"));
if (Directory.Exists(reactRoot))
    app.UseStaticFiles(new StaticFileOptions { FileProvider = new PhysicalFileProvider(reactRoot), RequestPath = "/react" });
app.UseStaticFiles();
app.MapGet("/react", () => Results.Redirect("/react/"));
app.MapFallback("/react/{**path}", () => Results.File(Path.Combine(reactRoot, "index.html"), "text/html; charset=utf-8"));
app.MapGet("/", () => Directory.Exists(reactRoot) ? Results.Redirect("/react/") : Results.File(Path.Combine(app.Environment.WebRootPath!, "login.html"), "text/html; charset=utf-8"));
app.MapGet("/legacy", (HttpContext http) => { var user = http.Request.Cookies["warehouse_session"]; var valid = app.Services.GetRequiredService<DataStoreService>().Data.Users.Any(x => x.Active && x.Username == user); var file = valid ? "app.html" : "login.html"; return Results.File(Path.Combine(app.Environment.WebRootPath!, file), "text/html; charset=utf-8"); });
app.Run();
